package EmployeeManagementSystem.controller;
import EmployeeManagementSystem.entity.*; import EmployeeManagementSystem.security.jwt.JwtUtil; import EmployeeManagementSystem.repository.EmployeeRepository; import EmployeeManagementSystem.service.EmployeeSurveyService; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import org.springframework.web.server.ResponseStatusException; import java.util.*;
@RestController @RequestMapping("/api/surveys") public class EmployeeSurveyController{
 private final EmployeeSurveyService service; private final JwtUtil jwt; private final EmployeeRepository employees;
 public EmployeeSurveyController(EmployeeSurveyService s,JwtUtil j,EmployeeRepository e){service=s;jwt=j;employees=e;}
 private String token(String a){if(a==null||!a.startsWith("Bearer "))throw new ResponseStatusException(HttpStatus.UNAUTHORIZED,"Authentication required.");return a.substring(7);} private String user(String a){return jwt.extractUsername(token(a));} private String role(String a){String r=jwt.extractRole(token(a));return r==null?"":r.replace("ROLE_","").toUpperCase();} private boolean mgmt(String r){return Set.of("ADMIN","HR").contains(r);}
 @GetMapping("/my") public List<EmployeeSurvey> my(@RequestHeader("Authorization") String a){return service.active();}
 @GetMapping public List<EmployeeSurvey> all(@RequestHeader("Authorization") String a){if(!mgmt(role(a)))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"HR/Admin access required.");return service.all();}
 @PostMapping public EmployeeSurvey create(@RequestHeader("Authorization")String a,@RequestBody EmployeeSurvey s){if(!mgmt(role(a)))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"HR/Admin access required.");return service.create(s);}
 @PutMapping("/{id}") public EmployeeSurvey update(@RequestHeader("Authorization")String a,@PathVariable Long id,@RequestBody EmployeeSurvey s){if(!mgmt(role(a)))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"HR/Admin access required.");return service.update(id,s);}
 @PatchMapping("/{id}/publish") public EmployeeSurvey publish(@RequestHeader("Authorization")String a,@PathVariable Long id){if(!mgmt(role(a)))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"HR/Admin access required.");return service.publish(id);}
 @PatchMapping("/{id}/close") public EmployeeSurvey close(@RequestHeader("Authorization")String a,@PathVariable Long id){if(!mgmt(role(a)))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"HR/Admin access required.");return service.close(id);}
 @GetMapping("/{id}/responses") public List<EmployeeSurveyResponse> responses(@RequestHeader("Authorization")String a,@PathVariable Long id){if(!mgmt(role(a)))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"HR/Admin access required.");return service.responses(id);}
 @GetMapping("/{id}/my-response") public Optional<EmployeeSurveyResponse> myResponse(@RequestHeader("Authorization")String a,@PathVariable Long id){return service.myResponse(id,user(a));}
 @PostMapping("/{id}/responses") public EmployeeSurveyResponse respond(@RequestHeader("Authorization")String a,@PathVariable Long id,@RequestBody Map<String,Object>b){String u=user(a);String n=employees.findByRegisterEmployee_UserId(u).map(e->e.getFullName()).orElse(u);try{return service.respond(id,u,n,Integer.valueOf(String.valueOf(b.get("rating"))),String.valueOf(b.getOrDefault("comment","")));}catch(Exception e){throw new ResponseStatusException(HttpStatus.BAD_REQUEST,e.getMessage());}}
}
